mapper.update:
UPDATE tb_excel_upload_batch
SET total_rows = #{totalRows},
    inserted_count = #{insertedCount},
    applied_date_count = #{appliedDateCount}
WHERE batch_id = #{batchId}

mapper.select:
SELECT batch_id, file_name, total_rows, inserted_count, applied_date_count, uploaded_at
FROM tb_excel_upload_batch
WHERE uploaded_at >= #{from}
  AND uploaded_at < #{toExclusive}
ORDER BY uploaded_at DESC, batch_id DESC

SELECT sale_date AS period_key, COALESCE(gasoline_diff_liter, 0) AS gasoline_diff, COALESCE(diesel_diff_liter, 0) AS diesel_diff FROM ( SELECT sale_date, gasoline_diff_liter, diesel_diff_liter, ROW_NUMBER() OVER (PARTITION BY sale_date ORDER BY row_id DESC) AS rn FROM tb_excel_upload_row
sale_date >= #{startDate}
AND sale_date <= #{endDate}
) ranked WHERE rn = 1 AND (gasoline_diff_liter IS NOT NULL OR diesel_diff_liter IS NOT NULL) ORDER BY sale_date ASC
